{v:'VER',what:'cloud-feel-role-net: a pillager who swaps to a better gun on the host has the same gun, role and coat on the partner window once the host words reach it',
 run:function(){
   if(!(window.__deploy&&window.__state&&window.__endRaid)) return 'SKIP: no raid here';
   var bad=[], g, rd, c, it=null, i, k, NK={}, oS=netSend, oSF=netSendFast, sent=[], cand=['gun_shotgun','gun_lmg','gun_sniper','gun_dmr','gun_carbine'], gk, r0, tmp, w0, words, r;
   for(k in NET) NK[k]=NET[k];
   try{
     __topClear(); __runPrep(); __resetCfg(); __pinDefaults(0); __deploy({kit:[],safe:null,mapIx:0,seed:4242});
     g=__state(); if(!g||g.over||!g.player) return 'SKIP: no live raid';
     if(g.sim) return 'SKIP: the fixture raid is a sim raid';
     g.player.iv=99;
     rd=g.ents.filter(function(x){ return x.kind==='raider'&&!x.merc&&!x.friendlyPC&&!x.ghost&&x.hp>0&&!x.downed&&!x.boss; })[0];
     if(!rd||!rd.wep||!rd.bag) return 'SKIP: staging: no pillager in the fixture raid';
     r0=raiderRole(rd);
     for(i=0;i<cand.length;i++){ gk=ITEMS[cand[i]]&&ITEMS[cand[i]].gk; if(gk&&(WTIER[gk]||0)>(WTIER[rd.wep.id]||0)){ tmp={kind:'raider',ident:rd.ident,name:rd.name,rig:rd.rig,wep:WEAPONS[gk]}; if(raiderRole(tmp)!==r0){ it=cand[i]; break; } } }
     if(!it) return 'SKIP: staging: no better gun that changes his role';
     NET.on=true; NET.role='host'; NET.seat=0; NET.specG=null; NET.up=[]; NET.upSeed=g.seed>>>0; NET.peers=[{seat:1,state:'in'}];
     netSend=function(q,m){ sent.push(JSON.parse(JSON.stringify(m))); return true; }; netSendFast=netSend;
     netEntsInit(g);
     if(!rd.nid) return 'SKIP: staging: the pillager has no body number';
     // player 2's copy of him, as the host announced him
     c=netEntMake(rd.nid,'raider',rd.x,rd.y); netEntFill(c,netEntNewWord(rd)); c.nIn=1;
     w0=rd.wep.id;
     rd.bag.push(it); rd.kitT=0; raiderUseKit(rd,0.016);
     if(rd.wep.id===w0) return 'SKIP: staging: the host pillager did not swap guns';
     words=sent.filter(function(m){ return m&&m.t==='ent'&&(m.id|0)===rd.nid; });
     // the partner window takes them
     NET.role='join'; NET.seat=1; NET.peers=[{seat:0,state:'in'}]; NET.entMap={}; NET.entMap[rd.nid]=c; NET.entGone={};
     for(i=0;i<words.length;i++){ r=netEntWord(NET.peers[0],words[i]); }
     if(c.wep.id!==rd.wep.id||raiderRole(c)!==raiderRole(rd)||raiderCoat(c)!==raiderCoat(rd))
       bad.push('after the swap the host has '+rd.wep.id+' ('+raiderRole(rd)+', '+raiderCoat(rd)+') but player 2 sees '+c.wep.id+' ('+raiderRole(c)+', '+raiderCoat(c)+'), '+words.length+' words about him');
   }catch(e){ bad.push('threw: '+(e&&e.message||e)); }
   finally{
     try{ netSend=oS; netSendFast=oSF; for(k in NET) if(!(k in NK)) delete NET[k]; for(k in NK) NET[k]=NK[k]; }catch(_h){}
     try{ __endRaid('abandon'); }catch(_e){}
     __topClear();
   }
   return bad.length?bad.join('; '):null; }},
